std::vector<std::pair<size_t, size_t>> collisions;
for (size_t i = 0; i < boxes.size(); i++) {
    for (size_t j = i + 1; j < boxes.size(); j++) {
        if (boxes[i].max.x >= boxes[j].min.x && boxes[i].min.x <= boxes[j].max.x &&
            boxes[i].max.y >= boxes[j].min.y && boxes[i].min.y <= boxes[j].max.y &&
            boxes[i].max.z >= boxes[j].min.z && boxes[i].min.z <= boxes[j].max.z) {
            collisions.push_back(std::make_pair(i, j));
        }
    }
}
return collisions; // END_CODE

